        if not isinstance(doc_id, str):
            return 400  # invalid id
        if doc_id in self.archived_documents:
            return 409  # archived document cannot be updated
        if doc_id in self.documents:
            self.documents[doc_id] = body
            return 200  # updated
        return 404  # missing document

    def archive(self, doc_id):
        """Archive the document with the given id."""
        if not isinstance(doc_id, str):
