            return 400  # invalid_id
        if doc_id in self.documents:
            return 409  # exists
        self.documents[doc_id] = body
        return 201  # created

    def read(self, doc_id):
        """Read the document with the given doc_id.

        Returns a tuple containing the status code and the body of the document,
        or None for the body if the document does not exist.
        """
        if not isinstance(doc_id, str):
            return 400, None  # invalid_id
        body = self.documents.get(doc_id)
        if body is None:
            return 404, None  # missing
        return 200, body

    def put(self, doc_id, body):
        """Update the document with the given doc_id to have the given body.

        Returns the status code 200 if the document is updated successfully,
        or 404 if the document with the given doc_id does not exist.
        """
        if not isinstance(doc_id, str):
            return 400  # invalid_id
        if doc_id not in self.documents:
            return 404  # missing
        self.documents[doc_id] = body
        return 200  # archived_put

    def archive(self, doc_id):
        """Archive the document with the given doc_id.

        Returns the status code 200 if the document is archived successfully,
        or 404 if the document with the given doc_id does not exist.
        """
        if not isinstance(doc_id, str):
            return 400  # invalid_id
        if doc_id not in self.documents:
            return 404  # missing
        return 200  # archived_put

    def list(self):
        """Return a sorted list of all document IDs, including archived ones.

        The list contains the IDs of all documents in the store, in sorted order.
        """
        return sorted(self.documents.keys())
