        self.documents = {}
        self.archived_documents = {}
        self.status_codes = {
            "invalid_id": 400,
            "exists": 409,
            "missing": 404,
            "archived_put": 409,
            "created": 201
        }

    def create(self, doc_id, body):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return self.status_codes["invalid_id"]

        if doc_id in self.documents:
            return self.status_codes["exists"]

        self.documents[doc_id] = body
        return self.status_codes["created"]

    def read(self, doc_id):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return self.status_codes["invalid_id"], None

        if doc_id in self.documents:
            return 200, self.documents[doc_id]
        elif doc_id in self.archived_documents:
            return 200, self.archived_documents[doc_id]
        return self.status_codes["missing"], None

    def put(self, doc_id, body):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return self.status_codes["invalid_id"]

        if doc_id in self.archived_documents:
            return self.status_codes["archived_put"]

        if doc_id in self.documents:
            self.documents[doc_id] = body
        else:
            self.archived_documents[doc_id] = body
        return 200

    def archive(self, doc_id):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return self.status_codes["invalid_id"]

        if doc_id in self.documents:
            self.archived_documents[doc_id] = self.documents.pop(doc_id)
        else:
            self.archived_documents[doc_id] = self.documents.pop(doc_id, None)
        return 200

    def list(self):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return self.status_codes["invalid_id"]

        return sorted(list(self.documents.keys()) + list(self.archived_documents.keys()))

